'use strict';

const http = require('http');
const https = require('https');
const fs = require('fs');
const path = require('path');
const { URL } = require('url');

const HOST = process.env.OTS_HOST || '127.0.0.1';
const PORT = Number(process.env.OTS_PORT || 8787);
const ROOT = path.resolve(__dirname);
const DEFAULT_HTML = process.env.OTS_HTML || 'generator-v15-real.html';

const ALLOWED_PROXY_ORIGINS = new Set([
    'https://alice.btc.calendar.opentimestamps.org',
    'https://bob.btc.calendar.opentimestamps.org',
    'https://finney.calendar.eternitywall.com',
    'https://a.pool.opentimestamps.org',
    'https://mempool.space',
    'https://blockstream.info',
    'https://blockchain.info',
    'https://api.blockchair.com'
]);

const MIME = {
    '.html':'text/html; charset=utf-8',
    '.htm':'text/html; charset=utf-8',
    '.js':'application/javascript; charset=utf-8',
    '.mjs':'application/javascript; charset=utf-8',
    '.css':'text/css; charset=utf-8',
    '.json':'application/json; charset=utf-8',
    '.txt':'text/plain; charset=utf-8',
    '.svg':'image/svg+xml',
    '.png':'image/png',
    '.jpg':'image/jpeg',
    '.jpeg':'image/jpeg',
    '.gif':'image/gif',
    '.webp':'image/webp',
    '.ico':'image/x-icon',
    '.pdf':'application/pdf',
    '.ots':'application/octet-stream',
    '.map':'application/json; charset=utf-8'
};

function headers(extra = {}) {
    return {
        'X-Content-Type-Options':'nosniff',
        'X-Frame-Options':'SAMEORIGIN',
        'Referrer-Policy':'no-referrer',
        'Permissions-Policy':'camera=(), microphone=(), geolocation=()',
        ...extra
    };
}

function send(res, code, body, extra = {}) {
    const data = Buffer.isBuffer(body) ? body : Buffer.from(String(body));
    res.writeHead(code, headers({
        'Content-Length': data.length,
        ...extra
    }));
    res.end(data);
}

function safeFile(urlPath) {
    let p;
    try { p = decodeURIComponent(urlPath); }
    catch { return null; }

    p = p.replace(/^\/+/, '');
    const file = path.resolve(ROOT, ...p.split('/'));
    const prefix = ROOT.endsWith(path.sep) ? ROOT : ROOT + path.sep;

    if (file !== ROOT && !file.startsWith(prefix)) return null;
    return file;
}

function proxyTarget(raw) {
    if (!raw) throw new Error('Missing target');

    const u = new URL(raw);
    if (u.protocol !== 'https:') throw new Error('Only HTTPS is allowed');
    if (!ALLOWED_PROXY_ORIGINS.has(u.origin)) {
        throw new Error('Target is not allowlisted');
    }

    u.username = '';
    u.password = '';
    return u;
}

function proxy(req, res, raw) {
    let target;
    try {
        target = proxyTarget(raw);
    } catch (e) {
        send(res, 403, JSON.stringify({ok:false,error:e.message}), {
            'Content-Type':'application/json; charset=utf-8'
        });
        return;
    }

    if (!['GET','HEAD'].includes(req.method)) {
        send(res, 405, 'Method Not Allowed', {'Allow':'GET, HEAD, OPTIONS'});
        return;
    }

    const request = https.request({
        hostname: target.hostname,
        port: target.port || 443,
        method: req.method,
        path: target.pathname + target.search,
        headers: {
            'User-Agent':'OTS-Enterprise-Server/1.0',
            'Accept':req.headers.accept || '*/*',
            'Accept-Encoding':'identity'
        }
    }, upstream => {
        res.writeHead(upstream.statusCode || 502, headers({
            'Content-Type':upstream.headers['content-type'] || 'application/octet-stream',
            'Cache-Control':upstream.headers['cache-control'] || 'no-store'
        }));

        if (req.method === 'HEAD') res.end();
        else upstream.pipe(res);
    });

    request.setTimeout(30000, () => request.destroy(new Error('Upstream timeout')));

    request.on('error', e => {
        if (!res.headersSent) {
            send(res, 502, JSON.stringify({
                ok:false,
                error:'Upstream request failed',
                detail:e.message
            }), {'Content-Type':'application/json; charset=utf-8'});
        } else {
            res.destroy();
        }
    });

    request.end();
}

function serve(req, res, pathname) {
    if (pathname === '/' || pathname === '') pathname = '/' + DEFAULT_HTML;

    const file = safeFile(pathname);
    if (!file) return send(res, 403, 'Forbidden');

    fs.stat(file, (err, stat) => {
        if (err || !stat.isFile()) return send(res, 404, 'Not Found');

        const type = MIME[path.extname(file).toLowerCase()] || 'application/octet-stream';

        res.writeHead(200, headers({
            'Content-Type':type,
            'Cache-Control':path.extname(file).toLowerCase() === '.html'
                ? 'no-cache'
                : 'public, max-age=3600'
        }));

        if (req.method === 'HEAD') return res.end();

        const stream = fs.createReadStream(file);
        stream.on('error', () => {
            if (!res.headersSent) send(res, 500, 'Internal Server Error');
            else res.destroy();
        });
        stream.pipe(res);
    });
}

const server = http.createServer((req, res) => {
    try {
        const u = new URL(req.url || '/', `http://${HOST}:${PORT}`);
        const p = u.pathname;

        console.log(new Date().toISOString(), req.method, p);

        if (req.method === 'OPTIONS') {
            return send(res, 204, '', {
                'Access-Control-Allow-Origin': `http://${HOST}:${PORT}`,
                'Access-Control-Allow-Methods':'GET, HEAD, OPTIONS',
                'Access-Control-Allow-Headers':'Content-Type, Accept',
                'Access-Control-Max-Age':'600'
            });
        }

        if (p === '/__ots_health') {
            return send(res, 200, JSON.stringify({
                ok:true,
                service:'OTS Enterprise Server',
                version:'1.0.0',
                node:process.version,
                host:HOST,
                port:PORT,
                root:ROOT,
                html:DEFAULT_HTML,
                timestamp:new Date().toISOString()
            }, null, 2), {
                'Content-Type':'application/json; charset=utf-8',
                'Cache-Control':'no-store'
            });
        }

        if (p === '/__ots_proxy') {
            return proxy(req, res, u.searchParams.get('target'));
        }

        if (p === '/favicon.ico' && !fs.existsSync(safeFile(p))) {
            return send(res, 204, '');
        }

        if (!['GET','HEAD'].includes(req.method)) {
            return send(res, 405, 'Method Not Allowed', {
                'Allow':'GET, HEAD, OPTIONS'
            });
        }

        serve(req, res, p);
    } catch (e) {
        console.error(e);
        if (!res.headersSent) send(res, 500, 'Internal Server Error');
        else res.destroy();
    }
});

server.on('error', e => {
    if (e.code === 'EADDRINUSE') {
        console.error(`Port ${PORT} is already in use.`);
    } else {
        console.error(e);
    }
    process.exitCode = 1;
});

server.listen(PORT, HOST, () => {
    console.log('');
    console.log('============================================================');
    console.log(' OTS ENTERPRISE SERVER - ONLINE');
    console.log('============================================================');
    console.log(` URL  : http://${HOST}:${PORT}/`);
    console.log(` HTML : ${DEFAULT_HTML}`);
    console.log(` ROOT : ${ROOT}`);
    console.log(` NODE : ${process.version}`);
    console.log(' PROXY: ENABLED / ALLOWLISTED');
    console.log('============================================================');
    console.log('');
    console.log('Open the application through HTTP, not file://');
    console.log('');
});

function shutdown(signal) {
    console.log(`${signal} received - shutting down`);
    server.close(() => process.exit(0));
    setTimeout(() => process.exit(1), 5000).unref();
}

process.on('SIGINT', () => shutdown('SIGINT'));
process.on('SIGTERM', () => shutdown('SIGTERM'));
